CREATE FUNCTION public.manager_check_task_sandbox() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF NEW.task_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM manager_tasks WHERE id=NEW.task_id AND workspace_id=NEW.workspace_id AND task_space_id IS NOT NULL) THEN RAISE EXCEPTION 'sandbox task must belong to TaskSpace'; END IF;
 RETURN NEW;
END $$;


--
-- Name: manager_consume_hook_ingress(uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.manager_consume_hook_ingress(w uuid, trigger uuid, tick timestamp with time zone DEFAULT clock_timestamp()) RETURNS boolean
    LANGUAGE sql
    AS $$
 WITH charged AS (
  INSERT INTO manager_hook_ingress_budgets AS b(workspace_id,trigger_id,credit_us,refilled_at)
  VALUES(w,trigger,9500000,tick)
  ON CONFLICT(workspace_id,trigger_id) DO UPDATE SET
   credit_us=LEAST(10000000,b.credit_us+FLOOR(EXTRACT(EPOCH FROM (GREATEST(b.refilled_at,EXCLUDED.refilled_at)-b.refilled_at))*1000000)::bigint)-500000,
   refilled_at=GREATEST(b.refilled_at,EXCLUDED.refilled_at)
  WHERE LEAST(10000000,b.credit_us+FLOOR(EXTRACT(EPOCH FROM (GREATEST(b.refilled_at,EXCLUDED.refilled_at)-b.refilled_at))*1000000)::bigint)>=500000
  RETURNING 1
 )
 SELECT EXISTS(SELECT 1 FROM charged);
$$;


