CREATE FUNCTION public.manager_human_continuation_context(r public.manager_human_requests, s public.manager_sessions, decision jsonb) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
 SELECT jsonb_build_object(
     'requestId', r.id, 'version', r.version::text,
     'questionDigest', encode(sha256(convert_to(r.question::text, 'UTF8')), 'hex'),
     'question', r.question, 'answer', decision,
     'source', jsonb_build_object('sessionId', s.id, 'turnId', r.turn_id,
         'inputId', r.input_id, 'authorityInputId', r.authority_input_id,
         'stopRevision', s.stop_revision, 'nativeSessionId', s.native_session_id,
         'configuration', s.configuration));
$$;


--
-- Name: manager_human_inbox_confirmation_allowed(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.manager_human_inbox_confirmation_allowed(inbound uuid, actor uuid, reply_input uuid DEFAULT NULL::uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
 SELECT manager_human_channel_inbox_current(inbound, actor)
 AND EXISTS(SELECT 1 FROM manager_channel_inbox n
 JOIN manager_conversations chat ON chat.id=n.conversation_id
 JOIN manager_human_requests r ON r.workspace_id=chat.workspace_id AND r.agent_id=chat.agent_id
 JOIN manager_sessions task ON task.id=r.session_id
 LEFT JOIN manager_conversations c ON c.id=task.conversation_id
 LEFT JOIN manager_task_spaces p ON p.id=task.task_space_id
 JOIN platform_agent_human_recipients h ON h.agent_id=r.agent_id
 WHERE n.id=inbound
 AND h.recipients @> jsonb_build_array(jsonb_build_object('id',r.question->>'recipient_id','ref',r.recipient))
 AND manager_human_recipient_matches(r.workspace_id,r.agent_id,r.recipient,actor,true)
 AND ((r.state='pending' AND task.lifecycle='active' AND COALESCE(c.lifecycle,p.lifecycle)='active'
       AND task.stop_revision=r.stop_revision AND manager_input_actor_allowed(r.authority_input_id))
      OR (reply_input IS NOT NULL AND r.answer_input_id=reply_input)));
$$;


--
-- Name: manager_human_recipient_matches(uuid, uuid, jsonb, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.manager_human_recipient_matches(workspace uuid, agent uuid, recipient jsonb, actor uuid, channel boolean) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
 SELECT manager_human_recipient_name(workspace,agent,recipient,false) IS NOT NULL AND CASE
 WHEN channel THEN EXISTS(
  SELECT 1 FROM manager_channel_principals p WHERE p.id=actor AND p.workspace_id=workspace
  AND p.provider=recipient->>'provider' AND p.binding_id::text=recipient->>'binding_id'
  AND p.identity_epoch::text=recipient->>'identity_epoch' AND p.external_tenant_id=recipient->>'tenant_id'
  AND p.external_user_id=recipient->>'external_id')
 ELSE recipient->>'provider'='web' AND recipient->>'external_id'=actor::text END;
$$;


