$$;


--
-- Name: manager_human_recipient_name(uuid, uuid, jsonb, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.manager_human_recipient_name(workspace uuid, agent uuid, recipient jsonb, require_employee_use boolean) RETURNS text
    LANGUAGE sql STABLE
    AS $$
 SELECT CASE
 WHEN NOT COALESCE(recipient @> jsonb_build_object('kind','user','workspace_id',workspace::text,'agent_id',agent::text),false) THEN NULL
 WHEN recipient->>'provider'='web' THEN (
  SELECT ac.name FROM platform_accounts ac
  WHERE ac.id=CASE WHEN pg_input_is_valid(recipient->>'external_id','uuid') THEN (recipient->>'external_id')::uuid END
  AND EXISTS(SELECT 1 FROM platform_agents a JOIN platform_members m
    ON m.workspace_id=a.workspace_id AND m.user_id=ac.id
    WHERE a.workspace_id=workspace AND a.id=agent AND a.enabled AND m.status='active')
  AND (NOT require_employee_use OR platform_agent_web_allowed(workspace,agent,ac.id)))
 ELSE (
  SELECT candidate.name
  FROM platform_channel_bindings b
  JOIN platform_agents a ON a.id=b.agent_id AND a.workspace_id=b.workspace_id
  CROSS JOIN LATERAL (
   SELECT u.display_name AS name FROM platform_channel_directory_state d
   JOIN platform_channel_directory_users u ON u.binding_id=d.binding_id
   WHERE b.provider IN ('feishu','dingtalk') AND d.binding_id=b.id AND d.identity_epoch=b.identity_epoch
   AND d.connection_generation=b.connection_generation AND d.external_tenant_id=b.external_tenant_id
   AND d.full_snapshot AND d.expires_at>now() AND u.user_id=recipient->>'external_id' AND u.status IN ('active','unknown')
   UNION ALL
   SELECT COALESCE(c.display_name,m.search_user_id)
   FROM platform_wecom_identity_mappings m LEFT JOIN platform_wecom_contacts c
    ON c.binding_id=m.binding_id AND c.identity_epoch=m.identity_epoch
    AND c.connection_generation=m.connection_generation AND c.search_user_id=m.search_user_id
   WHERE b.provider='wecom' AND m.binding_id=b.id AND m.identity_epoch=b.identity_epoch
   AND m.connection_generation=b.connection_generation AND m.callback_user_id=recipient->>'external_id'
  ) candidate
  WHERE b.workspace_id=workspace AND b.agent_id=agent AND a.enabled AND b.enabled
  AND b.id::text=recipient->>'binding_id' AND b.provider=recipient->>'provider'
  AND b.external_tenant_id<>'' AND b.external_tenant_id=recipient->>'tenant_id' AND b.bot_open_id<>''
  AND (b.provider='feishu' OR b.identity_verified_generation=b.connection_generation)
  AND b.identity_epoch::text=recipient->>'identity_epoch' AND b.connection_generation::text=recipient->>'connection_generation'
  AND recipient->>'identity_namespace'=CASE WHEN b.provider='feishu' THEN 'open_id' ELSE 'user_id' END
  AND (NOT require_employee_use OR platform_channel_actor_access_allowed(b.id,b.access,recipient->>'external_id',false)))
 END;
$$;


--
-- Name: manager_human_resume_allowed(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.manager_human_resume_allowed(input_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $_$
 SELECT EXISTS(SELECT 1 FROM manager_inputs i JOIN manager_human_requests r ON r.id=i.human_request_id
 JOIN manager_inputs root ON root.id=r.authority_input_id AND root.session_id=i.session_id AND root.workspace_id=i.workspace_id
 WHERE i.id=$1 AND (r.state='approved' OR (r.state='revised' AND r.answer->>'decision'='revise')) AND r.resume_input_id=i.id AND r.session_id=i.session_id
 AND i.admission_epoch=root.admission_epoch AND i.submitted_by IS NOT DISTINCT FROM root.submitted_by
 AND i.channel_principal_id IS NOT DISTINCT FROM root.channel_principal_id
 AND i.channel_generation IS NOT DISTINCT FROM root.channel_generation
 AND i.trigger_event_id IS NOT DISTINCT FROM root.trigger_event_id
 AND (manager_human_recipient_name(r.workspace_id,r.agent_id,r.recipient,false) IS NOT NULL)
 AND manager_input_actor_before_human_resume(root.id));
$_$;


--
-- Name: manager_input_actor_allowed(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.manager_input_actor_allowed(input_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $_$
 SELECT CASE WHEN i.work_assignment_id IS NOT NULL THEN manager_work_input_allowed(i.id)
 WHEN i.work_submission_id IS NOT NULL THEN manager_work_result_allowed(i.id)
 WHEN i.human_request_id IS NOT NULL AND EXISTS(SELECT 1 FROM manager_human_requests h JOIN manager_inputs root ON root.id=h.authority_input_id WHERE h.id=i.human_request_id AND root.work_submission_id IS NOT NULL)
 THEN EXISTS(SELECT 1 FROM manager_human_requests h JOIN manager_inputs root ON root.id=h.authority_input_id WHERE h.id=i.human_request_id
  AND h.resume_input_id=i.id AND (h.state='approved' OR (h.state='revised' AND h.answer->>'decision'='revise')) AND h.session_id=i.session_id
  AND i.admission_epoch=root.admission_epoch AND i.submitted_by IS NOT DISTINCT FROM root.submitted_by
  AND i.channel_principal_id IS NOT DISTINCT FROM root.channel_principal_id AND i.channel_generation IS NOT DISTINCT FROM root.channel_generation
  AND i.trigger_event_id IS NOT DISTINCT FROM root.trigger_event_id
  AND (manager_human_recipient_name(i.workspace_id,h.agent_id,h.recipient,false) IS NOT NULL)
  AND manager_work_result_allowed(root.id))
 ELSE manager_input_actor_before_work_items(i.id) END
 FROM manager_inputs i WHERE i.id=$1;
$_$;


--
-- Name: manager_input_actor_before_human_resume(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.manager_input_actor_before_human_resume(input_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
 SELECT CASE WHEN i.notification_id IS NULL OR c.channel_binding_id IS NULL THEN manager_input_actor_before_im_notifications(i.id) ELSE
 NOT i.trigger_agent_loop AND n.status='sent' AND n.context_status='admitted' AND s.conversation_id=n.conversation_id
 AND c.lifecycle='active' AND a.enabled AND a.admission_epoch=i.admission_epoch AND s.lifecycle='active' AND s.mode='chat'
 AND i.workspace_id=c.workspace_id AND a.id=c.agent_id AND c.channel_chat_type='group'
 AND b.enabled AND b.provider='feishu' AND b.agent_id=a.id AND b.identity_epoch=c.channel_identity_epoch
 AND b.external_tenant_id=c.channel_tenant_id AND b.external_tenant_id=n.target->>'tenant_id'
 AND b.connection_generation=(n.target->>'generation')::bigint
 AND manager_channel_group_allowed(b.id,b.identity_epoch,c.channel_tenant_id,c.external_chat_id,c.channel_thread_id)
 END FROM manager_inputs i JOIN manager_sessions s ON s.id=i.session_id LEFT JOIN manager_trigger_notifications n ON n.id=i.notification_id LEFT JOIN manager_conversations c ON c.id=s.conversation_id LEFT JOIN platform_agents a ON a.id=s.agent_id LEFT JOIN platform_channel_bindings b ON b.id=c.channel_binding_id WHERE i.id=input_id;
$$;


--
-- Name: manager_input_actor_before_im_notifications(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.manager_input_actor_before_im_notifications(input_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
 SELECT CASE WHEN i.notification_id IS NULL THEN manager_input_actor_before_notifications(i.id) ELSE
 NOT i.trigger_agent_loop AND n.status='sent' AND n.context_status='admitted' AND s.conversation_id=n.conversation_id
 AND c.lifecycle='active' AND a.enabled AND a.admission_epoch=i.admission_epoch AND s.lifecycle='active' AND s.mode='chat'
 AND i.workspace_id=c.workspace_id AND a.id=c.agent_id
 AND (c.web_group_id IS NOT NULL AND EXISTS(SELECT 1 FROM platform_web_groups g JOIN platform_web_group_agents ga ON ga.group_id=g.id WHERE g.id=c.web_group_id AND g.status='active' AND ga.agent_id=c.agent_id AND ga.status='active' AND g.admission_epoch=c.web_group_epoch AND ga.admission_epoch=c.web_group_agent_epoch))
 END FROM manager_inputs i JOIN manager_sessions s ON s.id=i.session_id LEFT JOIN manager_trigger_notifications n ON n.id=i.notification_id LEFT JOIN manager_conversations c ON c.id=s.conversation_id LEFT JOIN platform_agents a ON a.id=s.agent_id WHERE i.id=input_id;
$$;


--
-- Name: manager_input_actor_before_notifications(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.manager_input_actor_before_notifications(input_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
 SELECT CASE WHEN i.trigger_event_id IS NULL THEN manager_input_actor_before_triggers(i.id) ELSE manager_trigger_input_allowed(i.id) END FROM manager_inputs i WHERE i.id=input_id;
$$;


--
-- Name: manager_input_actor_before_task_spaces(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.manager_input_actor_before_task_spaces(input uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
 SELECT CASE WHEN c.web_group_id IS NULL THEN manager_input_actor_before_web_groups(i.id) ELSE manager_web_group_actor_allowed(c.id,i.submitted_by) AND EXISTS(SELECT 1 FROM platform_web_group_members gm WHERE gm.group_id=c.web_group_id AND gm.user_id=i.submitted_by AND gm.admission_epoch=i.web_group_member_epoch) END
 FROM manager_inputs i JOIN manager_sessions s ON s.id=i.session_id JOIN manager_conversations c ON c.id=s.conversation_id WHERE i.id=input; $$;


--
-- Name: manager_input_actor_before_triggers(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.manager_input_actor_before_triggers(input_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
 SELECT CASE WHEN s.task_space_id IS NULL THEN manager_input_actor_before_task_spaces(i.id)
 ELSE i.channel_principal_id IS NULL AND manager_task_space_actor_allowed(s.task_space_id,i.submitted_by::text,s.agent_id)
 AND s.task_space_agent_epoch=g.admission_epoch END
 FROM manager_inputs i JOIN manager_sessions s ON s.id=i.session_id
 LEFT JOIN manager_task_space_agents g ON g.task_space_id=s.task_space_id AND g.agent_id=s.agent_id WHERE i.id=input_id;
$$;


--
-- Name: manager_input_actor_before_web_groups(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.manager_input_actor_before_web_groups(input uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
 SELECT manager_input_actor_policy_allowed(input) AND NOT EXISTS(
 SELECT 1 FROM manager_inputs i JOIN manager_sessions s ON s.id=i.session_id
 JOIN manager_conversations c ON c.id=s.conversation_id
 JOIN manager_channel_principals p ON p.id=i.channel_principal_id
 LEFT JOIN manager_channel_inbox n ON n.input_id=i.id
 WHERE i.id=input AND c.channel_chat_type='group' AND (
 EXISTS(SELECT 1 FROM manager_channel_groups g WHERE g.binding_id=c.channel_binding_id AND g.identity_epoch=c.channel_identity_epoch AND g.external_tenant_id=c.channel_tenant_id AND g.external_chat_id=c.external_chat_id AND g.watermark_ms>COALESCE(n.trigger_created_at_ms,(extract(epoch FROM i.created_at)*1000)::bigint))
 OR EXISTS(SELECT 1 FROM manager_channel_group_members m WHERE m.binding_id=c.channel_binding_id AND m.identity_epoch=c.channel_identity_epoch AND m.external_tenant_id=c.channel_tenant_id AND m.external_chat_id=c.external_chat_id AND m.member_id=p.external_user_id AND m.watermark_ms>COALESCE(n.trigger_created_at_ms,(extract(epoch FROM i.created_at)*1000)::bigint))));
$$;


--
-- Name: manager_input_actor_before_work_items(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.manager_input_actor_before_work_items(input_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $_$
 SELECT CASE WHEN human_request_id IS NULL THEN manager_input_actor_before_human_resume(id) ELSE manager_human_resume_allowed(id) END
 FROM manager_inputs WHERE id=$1;
$_$;


--
-- Name: manager_input_actor_policy_allowed(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.manager_input_actor_policy_allowed(input uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
 SELECT EXISTS(SELECT 1 FROM manager_inputs i JOIN manager_sessions s ON s.id=i.session_id WHERE i.id=input AND
 ((i.submitted_by IS NOT NULL AND platform_agent_web_allowed(i.workspace_id,s.agent_id,i.submitted_by))
 OR (i.channel_principal_id IS NOT NULL AND manager_channel_actor_allowed(i.channel_principal_id,s.conversation_id,i.channel_generation) AND (i.channel_history_count=0 OR EXISTS(SELECT 1 FROM manager_channel_principals p JOIN platform_channel_bindings b ON b.id=p.binding_id WHERE p.id=i.channel_principal_id AND COALESCE((b.history->>'enabled')::boolean,false) AND COALESCE((b.history->>'limit')::integer,0)>=i.channel_history_count)))));
$$;


--
-- Name: manager_input_admission_allowed(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.manager_input_admission_allowed(input_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $_$
 SELECT CASE WHEN i.work_assignment_id IS NOT NULL OR i.work_submission_id IS NOT NULL OR i.human_request_id IS NOT NULL
 THEN manager_input_actor_allowed(i.id) ELSE manager_input_admission_before_work_items(i.id) END
 FROM manager_inputs i WHERE i.id=$1;
$_$;


--
-- Name: manager_input_admission_before_human_resume(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.manager_input_admission_before_human_resume(input_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
 SELECT CASE WHEN notification_id IS NULL THEN manager_input_admission_before_notifications(id) ELSE manager_input_actor_allowed(id) END FROM manager_inputs WHERE id=input_id;
$$;


--
-- Name: manager_input_admission_before_notifications(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.manager_input_admission_before_notifications(input_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
 SELECT CASE WHEN i.trigger_event_id IS NULL THEN manager_input_admission_before_triggers(i.id) ELSE manager_trigger_input_allowed(i.id) END FROM manager_inputs i WHERE i.id=input_id;
$$;


--
-- Name: manager_input_admission_before_task_spaces(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.manager_input_admission_before_task_spaces(input uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
 SELECT CASE WHEN c.web_group_id IS NULL THEN manager_input_admission_before_web_groups(i.id) ELSE manager_input_actor_allowed(i.id) END
 FROM manager_inputs i JOIN manager_sessions s ON s.id=i.session_id JOIN manager_conversations c ON c.id=s.conversation_id WHERE i.id=input; $$;


--
-- Name: manager_input_admission_before_triggers(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.manager_input_admission_before_triggers(input_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
 SELECT CASE WHEN s.task_space_id IS NULL THEN manager_input_admission_before_task_spaces(i.id)
 ELSE manager_input_actor_allowed(i.id) END FROM manager_inputs i JOIN manager_sessions s ON s.id=i.session_id WHERE i.id=input_id;
$$;


--
-- Name: manager_input_admission_before_web_groups(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.manager_input_admission_before_web_groups(input uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
 SELECT CASE WHEN i.trigger_agent_loop THEN manager_input_actor_allowed(i.id)
 ELSE i.channel_principal_id IS NULL OR EXISTS (
 SELECT 1 FROM manager_channel_principals p
 JOIN manager_sessions s ON s.id=i.session_id
 JOIN manager_conversations c ON c.id=s.conversation_id
 JOIN platform_channel_bindings b ON b.id=c.channel_binding_id
 WHERE p.id=i.channel_principal_id AND p.binding_id=b.id AND b.enabled
 AND b.connection_generation=i.channel_generation AND p.external_tenant_id=c.channel_tenant_id
 AND b.external_tenant_id=p.external_tenant_id
 AND b.identity_epoch=p.identity_epoch AND b.identity_epoch=c.channel_identity_epoch
 AND b.workspace_id=i.workspace_id AND p.workspace_id=i.workspace_id
 AND b.agent_id=s.agent_id
 AND (i.channel_history_count=0 OR (COALESCE((b.history->>'enabled')::boolean,false) AND COALESCE((b.history->>'limit')::integer,0)>=i.channel_history_count))
 ) END FROM manager_inputs i WHERE i.id=input;
$$;


--
-- Name: manager_input_admission_before_work_items(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.manager_input_admission_before_work_items(input_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $_$
 SELECT CASE WHEN human_request_id IS NULL THEN manager_input_admission_before_human_resume(id) ELSE manager_human_resume_allowed(id) END
 FROM manager_inputs WHERE id=$1;
$_$;


--
-- Name: manager_planned_task_input_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.manager_planned_task_input_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF EXISTS(SELECT 1 FROM manager_sessions s JOIN manager_tasks t ON t.id=s.task_id WHERE s.id=NEW.session_id AND t.planning_state<>'started') THEN
 RAISE EXCEPTION 'planned or canceled task cannot receive execution inputs' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: manager_resolve_task_agent(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.manager_resolve_task_agent() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF NEW.conversation_id IS NOT NULL THEN
   SELECT agent_id INTO NEW.agent_id FROM manager_conversations WHERE id=NEW.conversation_id AND workspace_id=NEW.workspace_id;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: manager_shared_history_allowed(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.manager_shared_history_allowed(query_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
 SELECT EXISTS(SELECT 1 FROM manager_group_history_queries q JOIN manager_group_history_grants g ON g.input_id=q.input_id AND g.session_id=q.session_id
 AND g.workspace_id=q.workspace_id AND g.agent_id=q.agent_id AND g.policy_id IS NOT DISTINCT FROM q.policy_id AND g.policy_version=q.policy_version AND g.edge_ordinal=q.edge_ordinal
 AND g.source_ref=q.source_ref AND g.target_ref=q.target_ref
 WHERE q.id=query_id AND q.expires_at>now() AND manager_shared_history_grant_allowed(g.id)
 AND (manager_sharing_scope_key(q.source_ref)=manager_sharing_scope_key(q.target_ref) OR NOT EXISTS(SELECT 1 FROM manager_group_sharing_lineage l WHERE l.workspace_id=q.workspace_id AND l.destination_key=manager_sharing_scope_key(q.source_ref)
 AND l.source_key<>manager_sharing_scope_key(q.target_ref) AND NOT EXISTS(
 SELECT 1 FROM manager_group_history_grants ancestor WHERE ancestor.input_id=q.input_id AND manager_sharing_scope_key(ancestor.source_ref)=l.source_key
 AND manager_sharing_scope_key(ancestor.target_ref)=manager_sharing_scope_key(q.target_ref) AND manager_shared_history_grant_allowed(ancestor.id)))));
$$;


--
-- Name: manager_shared_history_grant_allowed(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.manager_shared_history_grant_allowed(grant_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
 SELECT EXISTS(SELECT 1 FROM manager_group_history_grants g JOIN manager_group_history_grant_sets gs ON gs.input_id=g.input_id
 JOIN manager_inputs i ON i.id=g.input_id JOIN manager_sessions s ON s.id=g.session_id AND i.session_id=s.id
 JOIN manager_turns t ON t.id=s.active_turn_id AND t.input_id=i.id
 LEFT JOIN platform_group_sharing_policies p ON p.id=g.policy_id LEFT JOIN platform_group_sharing_edges e ON e.policy_id=p.id AND e.ordinal=g.edge_ordinal
 WHERE g.id=grant_id AND g.workspace_id=s.workspace_id AND g.agent_id=s.agent_id AND gs.session_id=s.id
 AND s.engine_id=gs.engine_id AND s.assignment_id=gs.assignment_id AND s.generation=gs.generation
 AND t.assignment_id=s.assignment_id AND t.generation=s.generation AND t.status='running' AND i.status='started' AND i.turn_id=t.id
 AND s.lifecycle='active' AND s.stop_revision=s.applied_stop_revision AND manager_input_actor_allowed(i.id)
 AND ((g.grant_kind='self' AND g.policy_id IS NULL AND g.source_ref=g.target_ref AND g.source_ref->>'kind'='group') OR (g.grant_kind='policy' AND p.workspace_id=g.workspace_id AND p.agent_id=g.agent_id AND p.enabled AND p.version=g.policy_version
 AND e.source_ref=g.source_ref AND e.target_ref=g.target_ref))
 AND manager_sharing_ref_current(g.source_ref,g.workspace_id,g.agent_id) AND manager_sharing_target_matches(i.id,g.target_ref));
$$;


--
-- Name: manager_shared_history_record_read(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.manager_shared_history_record_read(query_id uuid) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
 DECLARE q manager_group_history_queries%ROWTYPE;
 BEGIN
 SELECT * INTO q FROM manager_group_history_queries WHERE id=query_id;
 IF NOT FOUND OR q.status<>'completed' THEN RETURN false; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('sharing-lineage:'||q.workspace_id::text,0));
 IF NOT manager_shared_history_allowed(q.id) THEN RETURN false; END IF;
 INSERT INTO manager_group_sharing_lineage(workspace_id,destination_key,source_key,source_ref)
 VALUES(q.workspace_id,manager_sharing_scope_key(q.target_ref),manager_sharing_scope_key(q.source_ref),q.source_ref) ON CONFLICT DO NOTHING;
 INSERT INTO manager_group_sharing_lineage(workspace_id,destination_key,source_key,source_ref)
 SELECT q.workspace_id,manager_sharing_scope_key(q.target_ref),l.source_key,l.source_ref FROM manager_group_sharing_lineage l
 WHERE l.workspace_id=q.workspace_id AND l.destination_key=manager_sharing_scope_key(q.source_ref) ON CONFLICT DO NOTHING;
 INSERT INTO manager_group_history_reads(query_id,workspace_id,session_id,input_id,policy_id,policy_version,source_ref,target_ref)
 VALUES(q.id,q.workspace_id,q.session_id,q.input_id,q.policy_id,q.policy_version,q.source_ref,q.target_ref) ON CONFLICT DO NOTHING;
 RETURN true;
 END;
$$;


--
-- Name: manager_sharing_ref_current(jsonb, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.manager_sharing_ref_current(ref jsonb, workspace uuid, agent uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
 SELECT ref->>'workspace_id'=workspace::text AND ref->>'agent_id'=agent::text AND CASE
 WHEN ref->>'provider'='web' THEN CASE WHEN ref->>'kind'='user' THEN EXISTS(
 SELECT 1 FROM platform_members m WHERE m.workspace_id=workspace AND m.user_id::text=ref->>'external_id' AND m.status='active')
 WHEN ref->>'kind'='group' THEN EXISTS(SELECT 1 FROM platform_web_groups g JOIN platform_web_group_agents a ON a.group_id=g.id AND a.workspace_id=g.workspace_id
 WHERE g.workspace_id=workspace AND a.agent_id=agent AND g.id::text=ref->>'external_id' AND g.status='active' AND a.status='active'
 AND g.admission_epoch::text=ref->>'group_epoch' AND a.admission_epoch::text=ref->>'agent_epoch') ELSE false END
 ELSE EXISTS(SELECT 1 FROM platform_channel_bindings b WHERE b.id::text=ref->>'binding_id' AND b.workspace_id=workspace AND b.agent_id=agent
 AND b.enabled AND b.provider=ref->>'provider' AND b.external_tenant_id<>'' AND b.external_tenant_id=ref->>'tenant_id'
 AND b.identity_epoch::text=ref->>'identity_epoch' AND b.connection_generation::text=ref->>'connection_generation'
 AND (ref->>'kind'='user' OR b.config_revision::text=ref->>'config_revision') AND (b.provider='feishu' OR b.identity_verified_generation=b.connection_generation)
 AND CASE WHEN ref->>'kind'='group' THEN manager_channel_group_allowed(b.id,b.identity_epoch,b.external_tenant_id,ref->>'external_id','') AND (
 EXISTS(SELECT 1 FROM platform_channel_group_candidates x WHERE x.binding_id=b.id AND x.external_chat_id=ref->>'external_id' AND x.identity_epoch=b.identity_epoch AND x.connection_generation=b.connection_generation AND x.config_revision=b.config_revision AND x.external_tenant_id=b.external_tenant_id AND x.expires_at>now())
 OR EXISTS(SELECT 1 FROM platform_channel_observed_chats x WHERE x.binding_id=b.id AND x.identity_epoch=b.identity_epoch AND x.external_tenant_id=b.external_tenant_id AND x.external_chat_id=ref->>'external_id'))
 WHEN ref->>'kind'='user' THEN CASE WHEN b.provider='wecom' THEN EXISTS(SELECT 1 FROM platform_wecom_identity_mappings m WHERE m.binding_id=b.id AND m.identity_epoch=b.identity_epoch AND m.connection_generation=b.connection_generation AND m.callback_user_id=ref->>'external_id')
 ELSE EXISTS(SELECT 1 FROM platform_channel_directory_state d JOIN platform_channel_directory_users u ON u.binding_id=d.binding_id WHERE d.binding_id=b.id AND d.identity_epoch=b.identity_epoch AND d.connection_generation=b.connection_generation AND d.external_tenant_id=b.external_tenant_id AND d.expires_at>now() AND d.full_snapshot AND u.user_id=ref->>'external_id' AND u.status='active') END ELSE false END) END;
$$;


--
-- Name: manager_sharing_scope_key(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.manager_sharing_scope_key(ref jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
 SELECT jsonb_build_array(ref->>'workspace_id',ref->>'provider',CASE WHEN ref->>'provider'='wecom' AND ref->>'kind'='group' THEN '' ELSE COALESCE(ref->>'tenant_id','') END,ref->>'kind',COALESCE(ref->>'identity_namespace',''),ref->>'external_id')::text;
$$;


--
-- Name: manager_sharing_target_matches(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.manager_sharing_target_matches(input uuid, ref jsonb) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
 SELECT EXISTS(SELECT 1 FROM manager_inputs i JOIN manager_sessions s ON s.id=i.session_id JOIN manager_conversations c ON c.id=s.conversation_id
 LEFT JOIN manager_channel_principals p ON p.id=i.channel_principal_id
 WHERE i.id=input AND i.source_kind='user' AND s.mode='task' AND s.trigger_id IS NULL
 AND manager_sharing_ref_current(ref,s.workspace_id,s.agent_id)
 AND CASE WHEN ref->>'provider'='web' THEN c.channel_binding_id IS NULL AND CASE WHEN ref->>'kind'='group' THEN c.web_group_id::text=ref->>'external_id'
 AND c.web_group_epoch::text=ref->>'group_epoch' AND c.web_group_agent_epoch::text=ref->>'agent_epoch'
 ELSE c.web_group_id IS NULL AND c.created_by::text=ref->>'external_id' AND i.submitted_by::text=ref->>'external_id' END
 ELSE c.channel_binding_id::text=ref->>'binding_id' AND c.channel_identity_epoch::text=ref->>'identity_epoch' AND c.channel_tenant_id=ref->>'tenant_id'
 AND CASE WHEN ref->>'kind'='group' THEN c.channel_chat_type='group' AND c.external_chat_id=ref->>'external_id'
 ELSE c.channel_chat_type='direct' AND c.channel_created_by=p.id AND p.external_user_id=ref->>'external_id' END END);
$$;


--
-- Name: manager_task_space_actor_allowed(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.manager_task_space_actor_allowed(space uuid, actor text, employee uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
 SELECT EXISTS(SELECT 1 FROM manager_task_spaces p JOIN manager_task_space_agents g ON g.task_space_id=p.id
 JOIN platform_members m ON m.workspace_id=p.workspace_id AND m.user_id::text=actor AND m.status='active'
 WHERE p.id=space AND p.created_by::text=actor AND p.lifecycle='active' AND g.agent_id=employee AND g.status='active'
 AND platform_agent_web_allowed(p.workspace_id,employee,m.user_id));
$$;


--
-- Name: manager_trigger_admin_allowed(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.manager_trigger_admin_allowed(trigger_id uuid, actor text) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
 SELECT EXISTS(SELECT 1 FROM manager_triggers t JOIN platform_members m ON m.workspace_id=t.workspace_id AND m.user_id=t.created_by WHERE t.id=trigger_id AND t.created_by::text=actor AND m.status='active' AND m.role IN ('owner','admin'));
$$;


--
-- Name: manager_trigger_input_allowed(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.manager_trigger_input_allowed(input_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
 SELECT EXISTS(SELECT 1 FROM manager_inputs i JOIN manager_trigger_events e ON e.id=i.trigger_event_id
 JOIN manager_sessions s ON s.id=i.session_id JOIN manager_tasks k ON k.id=s.task_id
 JOIN manager_triggers t ON t.id=e.trigger_id JOIN platform_agents a ON a.id=t.agent_id
 JOIN manager_task_spaces p ON p.id=s.task_space_id
 WHERE i.id=input_id AND t.enabled AND a.enabled AND p.lifecycle='active'
 AND e.workspace_id=i.workspace_id AND s.workspace_id=t.workspace_id AND s.agent_id=t.agent_id
 AND e.binding_version=t.version AND s.trigger_id=t.id AND s.trigger_version=t.version
 AND k.trigger_id=t.id AND k.trigger_version=t.version AND e.task_id=k.id AND e.session_id=s.id
 AND e.input_id=i.id AND e.status='accepted' AND i.submitted_by IS NULL AND i.channel_principal_id IS NULL);
$$;


--
-- Name: manager_web_group_actor_allowed(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.manager_web_group_actor_allowed(conversation uuid, actor uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
 SELECT EXISTS(SELECT 1 FROM manager_conversations c JOIN platform_web_groups g ON g.id=c.web_group_id
 JOIN platform_web_group_agents ga ON ga.group_id=g.id AND ga.agent_id=c.agent_id
 WHERE c.id=conversation AND c.lifecycle='active' AND c.web_group_epoch=g.admission_epoch
 AND c.web_group_agent_epoch=ga.admission_epoch
 AND platform_web_group_agent_allowed(c.workspace_id,g.id,c.agent_id,actor)); $$;


--
-- Name: manager_work_cancel_event(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.manager_work_cancel_event() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 INSERT INTO manager_work_events(work_item_id,kind) VALUES(NEW.id,'cancelled');
 RETURN NEW;
END $$;


--
-- Name: manager_work_file_allowed(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.manager_work_file_allowed(grant_id uuid, file_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $_$
WITH RECURSIVE chain AS (
 SELECT s.boundary_id,s.parent_boundary_id FROM manager_work_file_selections s WHERE s.boundary_id=$1 AND s.file_id=$2
 UNION ALL SELECT s.boundary_id,s.parent_boundary_id FROM chain c JOIN manager_work_file_selections s ON s.boundary_id=c.parent_boundary_id AND s.file_id=$2)
 SELECT EXISTS(SELECT FROM chain) AND NOT EXISTS(SELECT FROM chain c JOIN manager_work_boundaries b ON b.id=c.boundary_id
 JOIN manager_sessions src ON src.id=b.session_id JOIN platform_agents e ON e.id=src.agent_id
 JOIN manager_inputs source_input ON source_input.id=b.input_id
 LEFT JOIN manager_work_assignments source_assignment ON source_assignment.id=source_input.work_assignment_id
 JOIN manager_work_items w ON w.id=b.work_item_id JOIN manager_sessions root ON root.id=w.root_session_id
 JOIN platform_agents root_agent ON root_agent.id=root.agent_id JOIN manager_inputs authority ON authority.id=w.authority_input_id
 LEFT JOIN platform_agents target ON target.id=NULLIF(b.payload->>'target_employee_id','')::uuid
 WHERE b.state<>'committed' OR (source_assignment.id IS NOT NULL AND NOT manager_work_receiver_allows(e.id,source_assignment.source_agent_id))
 OR NOT root_agent.enabled OR authority.admission_epoch<>root_agent.admission_epoch OR source_input.admission_epoch<>e.admission_epoch OR NOT e.enabled OR src.lifecycle<>'active' OR src.stop_revision<>b.stop_revision
 OR root.lifecycle<>'active' OR root.stop_revision<>w.root_stop_revision OR NOT manager_input_actor_before_work_items(w.authority_input_id)
 OR (b.kind='handoff' AND (NOT target.enabled OR target.admission_epoch<>b.target_epoch OR NOT manager_work_receiver_allows(target.id,src.agent_id))));
$_$;


--
-- Name: manager_work_input_allowed(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.manager_work_input_allowed(input_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
 SELECT manager_work_input_before_policy(input_id) AND EXISTS(SELECT FROM manager_inputs i JOIN manager_work_assignments a
 ON a.id=i.work_assignment_id WHERE i.id=input_id AND manager_work_receiver_allows(a.target_agent_id,a.source_agent_id));
$$;


--
-- Name: manager_work_input_before_policy(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.manager_work_input_before_policy(input_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $_$
 SELECT EXISTS(
 SELECT 1 FROM manager_inputs i
 JOIN manager_work_assignments a ON a.id=i.work_assignment_id AND a.session_id=i.session_id
 JOIN manager_work_items w ON w.id=a.work_item_id AND w.workspace_id=i.workspace_id
 JOIN manager_sessions s ON s.id=a.session_id AND s.workspace_id=w.workspace_id AND s.task_space_id=w.task_space_id AND s.agent_id=a.target_agent_id
 JOIN manager_task_spaces p ON p.id=w.task_space_id AND p.lifecycle='active'
 JOIN platform_agents e ON e.id=a.target_agent_id AND e.enabled
 JOIN manager_sessions root ON root.id=w.root_session_id AND root.lifecycle='active' AND root.stop_revision=w.root_stop_revision
 JOIN platform_agents ra ON ra.id=root.agent_id AND ra.enabled
 JOIN manager_inputs authority ON authority.id=w.authority_input_id AND authority.session_id=root.id AND authority.admission_epoch=ra.admission_epoch
 LEFT JOIN manager_conversations c ON c.id=root.conversation_id
 LEFT JOIN manager_task_spaces rs ON rs.id=root.task_space_id
 WHERE i.id=$1 AND i.admission_epoch=e.admission_epoch AND w.status='working' AND w.current_assignment_id=a.id
 AND COALESCE(c.lifecycle,rs.lifecycle)='active' AND manager_input_actor_before_work_items(w.authority_input_id)
 AND (i.source_kind IN ('work_item_assignment','work_item_amendment') OR EXISTS(
   SELECT 1 FROM manager_human_requests h JOIN manager_inputs original ON original.id=h.authority_input_id
   WHERE h.id=i.human_request_id AND h.resume_input_id=i.id AND (h.state='approved' OR (h.state='revised' AND h.answer->>'decision'='revise')) AND h.session_id=s.id
   AND original.work_assignment_id=a.id AND original.source_kind IN ('work_item_assignment','work_item_amendment')
   AND (manager_human_recipient_name(w.workspace_id,e.id,h.recipient,false) IS NOT NULL))));
$_$;


--
-- Name: manager_work_package_allowed(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.manager_work_package_allowed(p jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
 SELECT COALESCE((p->>'enabled')::boolean,false) AND COALESCE(p->'conversation_scope','null'::jsonb)='null'
 AND p#>>'{scope,mode}'='inherit_with_blacklist'
 AND NOT EXISTS (SELECT 1 FROM unnest(ARRAY['allow_member_ids','deny_member_ids','allow','deny']) AS k
  WHERE COALESCE(p->'scope'->k,'null'::jsonb) NOT IN ('null','[]'));
$$;


--
-- Name: manager_work_package_allows(jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.manager_work_package_allows(p jsonb, source uuid) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
 SELECT CASE WHEN COALESCE(p->'work_scope','null'::jsonb)='null' THEN manager_work_package_allowed(p)
 ELSE (p->>'enabled')::boolean AND manager_work_scope_allows(p->'work_scope',source) END;
$$;


--
-- Name: manager_work_receiver_allows(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.manager_work_receiver_allows(target uuid, source uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
 SELECT COALESCE((SELECT manager_work_scope_allows(scope,source) FROM platform_work_receivers WHERE agent_id=target),true);
$$;


--
-- Name: manager_work_result_allowed(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.manager_work_result_allowed(input_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $_$
 SELECT EXISTS(SELECT 1 FROM manager_inputs i JOIN manager_work_boundaries b ON b.id=i.work_submission_id
 JOIN manager_work_items w ON w.id=b.work_item_id AND w.root_session_id=i.session_id
 JOIN manager_sessions s ON s.id=i.session_id
 JOIN manager_inputs original ON original.id=w.authority_input_id AND original.session_id=s.id
 WHERE i.id=$1 AND b.kind='submit' AND b.state='committed'
 AND w.current_submission_id=b.id AND w.status IN ('awaiting_acceptance','completed')
 AND s.stop_revision=w.root_stop_revision
 AND i.admission_epoch=original.admission_epoch
 AND i.submitted_by IS NOT DISTINCT FROM original.submitted_by
 AND i.channel_principal_id IS NOT DISTINCT FROM original.channel_principal_id
 AND i.channel_generation IS NOT DISTINCT FROM original.channel_generation
 AND i.trigger_event_id IS NOT DISTINCT FROM original.trigger_event_id
 AND manager_input_actor_before_work_items(original.id));
$_$;


--
-- Name: manager_work_review_ready(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.manager_work_review_ready(session_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
 SELECT EXISTS(SELECT FROM manager_sessions s WHERE s.id=session_id AND (
 EXISTS(SELECT FROM platform_model_profiles p WHERE p.id=NULLIF(s.configuration->>'model_profile_id','')::uuid AND p.workspace_id=s.workspace_id AND p.enabled AND p.validated AND p.protocol=s.configuration->>'protocol' AND p.base_url=s.configuration->>'base_url' AND p.model_id=s.configuration->>'model_id')
 OR EXISTS(SELECT FROM platform_proxy_models p JOIN platform_agent_model_keys k ON k.agent_id=s.agent_id
 WHERE p.id=NULLIF(s.configuration->>'platform_model_id','')::uuid AND p.protocol=s.configuration->>'protocol' AND p.enabled AND p.validated)));
$$;


--
-- Name: manager_work_scope_allows(jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.manager_work_scope_allows(scope jsonb, source uuid) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
 SELECT CASE scope->>'mode' WHEN 'inherit' THEN true WHEN 'all' THEN true
 WHEN 'allowlist' THEN COALESCE(scope->'employee_ids' ? source::text,false)
 WHEN 'denylist' THEN NOT COALESCE(scope->'employee_ids' ? source::text,false) ELSE false END;
$$;


--
-- Name: manager_work_started(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.manager_work_started() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 INSERT INTO manager_work_events(work_item_id,kind,agent_id,turn_id)
 SELECT a.work_item_id,'started',a.target_agent_id,NEW.id FROM manager_inputs i JOIN manager_work_assignments a ON a.id=i.work_assignment_id
 WHERE i.id=NEW.input_id AND i.source_kind='work_item_assignment';
 RETURN NEW;
END $$;


--
-- Name: platform_agent_usage_projection(jsonb, text, uuid, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_agent_usage_projection(config jsonb, provider text, binding uuid, epoch bigint) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    AS $$
 WITH selectors AS (
 SELECT side,s FROM (VALUES ('allow'),('deny')) sides(side),LATERAL jsonb_array_elements(COALESCE(config->'access'->side,'[]'::jsonb)) s
 WHERE s->>'channel'=provider AND (provider='web' OR (s->>'binding_id'=binding::text AND s->>'identity_epoch'=epoch::text))
 ), parts AS (
 SELECT jsonb_build_object(
 'mode',COALESCE(config#>>'{access,mode}','allowlist'),'group_members_enabled',COALESCE((config#>>'{access,group_members_enabled}')::boolean,true),
 'allow_ids',COALESCE((SELECT jsonb_agg(s->>'id') FROM selectors WHERE side='allow' AND s->>'kind'='user'),'[]'::jsonb),
 'deny_ids',COALESCE((SELECT jsonb_agg(s->>'id') FROM selectors WHERE side='deny' AND s->>'kind'='user'),'[]'::jsonb),
 'allow_chat_ids',COALESCE((SELECT jsonb_agg(s->>'id') FROM selectors WHERE side='allow' AND s->>'kind'='group'),'[]'::jsonb),
 'deny_chat_ids',COALESCE((SELECT jsonb_agg(s->>'id') FROM selectors WHERE side='deny' AND s->>'kind'='group'),'[]'::jsonb),
 'allow_department_ids',COALESCE((SELECT jsonb_agg(s->>'id') FROM selectors WHERE side='allow' AND s->>'kind'='department'),'[]'::jsonb),
 'deny_department_ids',COALESCE((SELECT jsonb_agg(s->>'id') FROM selectors WHERE side='deny' AND s->>'kind'='department'),'[]'::jsonb),
 'allow_department_rules',COALESCE((SELECT jsonb_agg(jsonb_build_object('department_id',s->>'id','include_descendants',COALESCE((s->>'include_descendants')::boolean,false))) FROM selectors WHERE side='allow' AND s->>'kind'='department'),'[]'::jsonb),
 'deny_department_rules',COALESCE((SELECT jsonb_agg(jsonb_build_object('department_id',s->>'id','include_descendants',COALESCE((s->>'include_descendants')::boolean,false))) FROM selectors WHERE side='deny' AND s->>'kind'='department'),'[]'::jsonb)
 ) AS access
 )
 SELECT jsonb_build_object('access',access,'trigger',jsonb_build_object(
 'mention',CASE WHEN provider IN ('dingtalk','wecom') THEN true ELSE COALESCE((config#>>'{trigger,mention}')::boolean,true) END,
 'keywords',COALESCE((SELECT jsonb_agg(r->>'text') FROM jsonb_array_elements(COALESCE(config#>'{trigger,keywords}','[]'::jsonb)) r WHERE provider IN ('web','feishu') AND r->'channels' ? provider AND COALESCE((r->>'enabled')::boolean,true)),'[]'::jsonb),
 'regexes',COALESCE((SELECT jsonb_agg(r->>'text') FROM jsonb_array_elements(COALESCE(config#>'{trigger,regexes}','[]'::jsonb)) r WHERE provider IN ('web','feishu') AND r->'channels' ? provider AND COALESCE((r->>'enabled')::boolean,true)),'[]'::jsonb)),
 'history',jsonb_build_object('enabled',COALESCE((config#>>'{history,enabled}')::boolean,false) AND provider IN ('web','feishu','wecom') AND COALESCE(config#>'{history,channels}','[]'::jsonb) ? provider,'limit',COALESCE((config#>>'{history,limit}')::integer,20))) FROM parts;
$$;


--
-- Name: platform_agent_web_allowed(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_agent_web_allowed(workspace uuid, agent uuid, actor uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $_$
 SELECT EXISTS(SELECT 1 FROM platform_agents a JOIN platform_members m ON m.workspace_id=a.workspace_id AND m.user_id=$3 AND m.status='active'
 CROSS JOIN LATERAL (SELECT platform_agent_usage_projection(a.usage_config,'web',NULL,0)->'access' AS access) p
 WHERE a.workspace_id=$1 AND a.id=$2 AND a.enabled AND NOT (p.access->'deny_ids' ? $3::text)
 AND (p.access->>'mode'='all' OR p.access->'allow_ids' ? $3::text));
$_$;


--
-- Name: platform_channel_actor_access_allowed(uuid, jsonb, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_channel_actor_access_allowed(binding uuid, policy jsonb, person text, group_chat boolean) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
 SELECT NOT COALESCE(policy->'deny_ids','[]'::jsonb) ? person
 AND NOT COALESCE(platform_channel_directory_department_match(binding,person,COALESCE(NULLIF(policy->'deny_department_rules','null'::jsonb),policy->'deny_department_ids')),true)
 AND ((group_chat AND COALESCE((policy->>'group_members_enabled')::boolean,false)) OR policy->>'mode' IN ('all','denylist')
 OR (policy->>'mode'='allowlist' AND (COALESCE(policy->'allow_ids','[]'::jsonb) ? person
 OR COALESCE(platform_channel_directory_department_match(binding,person,COALESCE(NULLIF(policy->'allow_department_rules','null'::jsonb),policy->'allow_department_ids')),false))));
$$;


--
-- Name: platform_channel_directory_department_match(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_channel_directory_department_match(binding uuid, person text, departments jsonb) RETURNS boolean
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE member_departments jsonb; rule jsonb; target text; recursive boolean; start_id text; next_id text; parent text; visited text[]; uncertain boolean := false; steps integer := 0;
BEGIN
 IF jsonb_array_length(COALESCE(departments,'[]'::jsonb))=0 THEN RETURN false; END IF;
 SELECT u.department_ids INTO member_departments FROM platform_channel_directory_users u
 JOIN platform_channel_directory_state d ON d.binding_id=u.binding_id JOIN platform_channel_bindings b ON b.id=d.binding_id
 WHERE u.binding_id=binding AND u.user_id=person AND u.memberships_known AND u.status<>'inactive'
 AND d.full_snapshot AND d.expires_at>now() AND b.enabled AND b.identity_epoch=d.identity_epoch
 AND b.connection_generation=d.connection_generation AND (b.provider='feishu' OR b.identity_verified_generation=b.connection_generation) AND b.external_tenant_id<>'' AND b.external_tenant_id=d.external_tenant_id;
 IF NOT FOUND THEN RETURN NULL; END IF;
 -- Resolve all direct evidence before spending the bounded ancestor budget.
 FOR rule IN SELECT value FROM jsonb_array_elements(departments) LOOP
  target := CASE WHEN jsonb_typeof(rule)='string' THEN rule#>>'{}' ELSE rule->>'department_id' END;
  IF member_departments ? target THEN RETURN true; END IF;
 END LOOP;
 FOR rule IN SELECT value FROM jsonb_array_elements(departments) LOOP
  target := CASE WHEN jsonb_typeof(rule)='string' THEN rule#>>'{}' ELSE rule->>'department_id' END;
  recursive := COALESCE((rule->>'include_descendants')::boolean,false);
  IF target IS NULL OR target='' THEN uncertain:=true; CONTINUE; END IF;
  IF member_departments ? target THEN RETURN true; END IF;
  IF NOT recursive THEN CONTINUE; END IF;
  FOR start_id IN SELECT jsonb_array_elements_text(member_departments) LOOP
   next_id:=start_id; visited:=ARRAY[]::text[];
   WHILE next_id<>'' LOOP
    IF next_id=ANY(visited) OR cardinality(visited)>=100 THEN uncertain:=true; EXIT; END IF;
    IF next_id=target THEN RETURN true; END IF;
    visited:=array_append(visited,next_id);
    steps:=steps+1;
    IF steps>10000 THEN RETURN NULL; END IF;
    SELECT parent_id INTO parent FROM platform_channel_directory_departments WHERE binding_id=binding AND department_id=next_id;
    IF NOT FOUND THEN uncertain:=true; EXIT; END IF;
    next_id:=parent;
   END LOOP;
  END LOOP;
 END LOOP;
 IF uncertain THEN RETURN NULL; END IF;
 RETURN false;
END;
$$;


--
-- Name: platform_channel_directory_display_name(uuid, bigint, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_channel_directory_display_name(binding uuid, epoch bigint, tenant text, person text) RETURNS text
    LANGUAGE sql STABLE
    AS $$
 SELECT u.display_name FROM platform_channel_directory_users u
 JOIN platform_channel_directory_state d ON d.binding_id=u.binding_id
 JOIN platform_channel_bindings b ON b.id=d.binding_id
 WHERE u.binding_id=binding AND u.user_id=person AND u.status='active' AND d.full_snapshot AND d.expires_at>now()
 AND b.enabled AND (b.provider='feishu' OR b.identity_verified_generation=b.connection_generation) AND b.identity_epoch=epoch AND d.identity_epoch=b.identity_epoch
 AND b.connection_generation=d.connection_generation
 AND b.external_tenant_id=tenant AND d.external_tenant_id=tenant;
$$;


--
-- Name: platform_check_oauth_client_owner(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_check_oauth_client_owner() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF NEW.oauth_client_id IS NOT NULL AND NOT EXISTS (SELECT FROM platform_plugin_oauth_clients c
   WHERE c.id=NEW.oauth_client_id AND c.workspace_id IS NOT DISTINCT FROM NEW.workspace_id AND c.issuer=NEW.oauth_issuer) THEN
   RAISE EXCEPTION 'OAuth application owner or issuer mismatch' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: platform_check_plugin_owner(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_check_plugin_owner() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE owner_id uuid;
BEGIN
 IF NEW.plugin_id IS NULL THEN RETURN NEW; END IF;
 SELECT workspace_id INTO STRICT owner_id FROM platform_plugins WHERE id=NEW.plugin_id;
 IF TG_TABLE_NAME='platform_agent_template_version_resources' THEN
  IF owner_id IS NOT DISTINCT FROM NEW.source_workspace_id THEN RETURN NEW; END IF;
 ELSIF owner_id IS NOT DISTINCT FROM NEW.workspace_id OR
       (owner_id IS NULL AND TG_TABLE_NAME<>'platform_plugin_versions') THEN
  RETURN NEW;
 END IF;
 RAISE EXCEPTION 'plugin scope mismatch' USING ERRCODE='23514';
END $$;


--
-- Name: platform_check_skill_owner(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_check_skill_owner() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE owner_id uuid;
BEGIN
 IF NEW.skill_id IS NULL THEN RETURN NEW; END IF;
 SELECT workspace_id INTO STRICT owner_id FROM platform_skills WHERE id=NEW.skill_id;
 IF TG_TABLE_NAME='platform_agent_template_version_resources' THEN
  IF owner_id IS NOT DISTINCT FROM NEW.source_workspace_id THEN RETURN NEW; END IF;
 ELSIF owner_id IS NOT DISTINCT FROM NEW.workspace_id OR
       (owner_id IS NULL AND TG_TABLE_NAME<>'platform_skill_versions') THEN
  RETURN NEW;
 END IF;
 RAISE EXCEPTION 'skill scope mismatch' USING ERRCODE='23514';
END $$;


--
-- Name: platform_plugin_connection_owner(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_plugin_connection_owner(w uuid, a uuid, p uuid) RETURNS uuid
    LANGUAGE sql STABLE
    AS $$SELECT a FROM platform_agent_plugin_connection_settings WHERE workspace_id=w AND agent_id=a AND plugin_id=p AND source='agent'$$;


--
-- Name: platform_resource_owner_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_resource_owner_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF NEW.workspace_id IS DISTINCT FROM OLD.workspace_id THEN
  RAISE EXCEPTION 'resource owner is immutable' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: platform_web_group_agent_allowed(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_web_group_agent_allowed(workspace uuid, group_id uuid, agent uuid, actor uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $_$
 SELECT platform_web_group_member_allowed($1,$2,$4) AND EXISTS(
 SELECT 1 FROM platform_web_group_agents ga JOIN platform_agents a ON a.id=ga.agent_id AND a.workspace_id=ga.workspace_id
 CROSS JOIN LATERAL (SELECT platform_agent_usage_projection(a.usage_config,'web',NULL,0)->'access' AS access) p
 WHERE ga.group_id=$2 AND ga.workspace_id=$1 AND ga.agent_id=$3 AND ga.status='active' AND a.enabled
 AND NOT (p.access->'deny_ids' ? $4::text) AND ((p.access->>'group_members_enabled')::boolean OR p.access->>'mode'='all' OR p.access->'allow_ids' ? $4::text)
 AND NOT (p.access->'deny_chat_ids' ? $2::text) AND (jsonb_array_length(p.access->'allow_chat_ids')=0 OR p.access->'allow_chat_ids' ? $2::text));
$_$;


--
-- Name: platform_web_group_member_allowed(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_web_group_member_allowed(workspace uuid, group_id uuid, actor uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $_$
 SELECT EXISTS(SELECT 1 FROM platform_web_groups g JOIN platform_web_group_members gm ON gm.group_id=g.id AND gm.workspace_id=g.workspace_id JOIN platform_members m ON m.workspace_id=g.workspace_id AND m.user_id=gm.user_id WHERE g.id=$2 AND g.workspace_id=$1 AND g.status='active' AND gm.user_id=$3 AND gm.status='active' AND m.status='active');
$_$;


--
-- Name: platform_channel_bindings; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.platform_channel_bindings (
    id uuid NOT NULL,
    workspace_id uuid NOT NULL,
    agent_id uuid NOT NULL,
    provider text NOT NULL,
    identity_epoch bigint DEFAULT 1 NOT NULL,
    connection_generation bigint NOT NULL,
    rules_version bigint NOT NULL,
    config_revision bigint NOT NULL,
    enabled boolean DEFAULT false NOT NULL,
    app_id text NOT NULL,
    external_tenant_id text DEFAULT ''::text NOT NULL,
    bot_open_id text DEFAULT ''::text NOT NULL,
    credential_ciphertext bytea NOT NULL,
    trigger jsonb NOT NULL,
    history jsonb NOT NULL,
    access jsonb NOT NULL,
    applied_generation bigint DEFAULT 0 NOT NULL,
    applied_rules_version bigint DEFAULT 0 NOT NULL,
    applied_revision bigint DEFAULT 0 NOT NULL,
    applied_status text DEFAULT 'pending'::text NOT NULL,
    applied_error text DEFAULT ''::text NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    identity_verified_generation bigint DEFAULT 0 NOT NULL,
    CONSTRAINT platform_channel_bindings_config_revision_check CHECK ((config_revision > 0)),
    CONSTRAINT platform_channel_bindings_connection_generation_check CHECK ((connection_generation > 0)),
    CONSTRAINT platform_channel_bindings_identity_epoch_check CHECK ((identity_epoch > 0)),
    CONSTRAINT platform_channel_bindings_provider_check CHECK ((provider = ANY (ARRAY['feishu'::text, 'dingtalk'::text, 'wecom'::text]))),
    CONSTRAINT platform_channel_bindings_rules_version_check CHECK ((rules_version > 0))
);


--
-- Name: platform_wecom_carry_contacts(public.platform_channel_bindings, bigint, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_wecom_carry_contacts(b public.platform_channel_bindings, previous_generation bigint, confirmed_generation bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
 -- During upgrade there may be independent proofs from several generations.
 -- Import only unambiguous pairs. On a normal rotation the last confirmed
 -- generation already contains the reconciled set.
 WITH pairs AS (
   SELECT DISTINCT ON (search_user_id,callback_user_id) m.* FROM platform_wecom_identity_mappings m
   WHERE m.binding_id=b.id AND m.identity_epoch=b.identity_epoch AND m.connection_generation<confirmed_generation
     AND (previous_generation IS NULL OR m.connection_generation=previous_generation)
   ORDER BY search_user_id,callback_user_id,connection_generation DESC
 ), candidates AS (
   SELECT p.*,count(*) OVER (PARTITION BY search_user_id) AS callbacks,
          count(*) OVER (PARTITION BY callback_user_id) AS people FROM pairs p
 )
 INSERT INTO platform_wecom_identity_mappings(binding_id,identity_epoch,connection_generation,search_user_id,callback_user_id,verification_id,verified_at)
 SELECT binding_id,identity_epoch,confirmed_generation,search_user_id,callback_user_id,verification_id,verified_at FROM candidates
 WHERE callbacks=1 AND people=1 ON CONFLICT DO NOTHING;

 INSERT INTO platform_wecom_contacts(binding_id,identity_epoch,connection_generation,search_user_id,display_name,department_paths,expires_at)
 SELECT DISTINCT ON (c.search_user_id) b.id,b.identity_epoch,confirmed_generation,c.search_user_id,c.display_name,c.department_paths,c.expires_at
 FROM platform_wecom_identity_mappings dest
 JOIN platform_wecom_identity_mappings src USING(binding_id,identity_epoch,search_user_id,callback_user_id)
 JOIN platform_wecom_contacts c USING(binding_id,identity_epoch,search_user_id)
 WHERE dest.binding_id=b.id AND dest.identity_epoch=b.identity_epoch AND dest.connection_generation=confirmed_generation
   AND src.connection_generation=c.connection_generation AND src.connection_generation<confirmed_generation
   AND (previous_generation IS NULL OR src.connection_generation=previous_generation)
 ORDER BY c.search_user_id,c.connection_generation DESC
 ON CONFLICT DO NOTHING;

 -- Refresh only saved recipients backed by the same proven pair in both
 -- generations. Requests that were already issued retain their dispatch fences.
 UPDATE platform_agent_human_recipients h SET recipients=renewed.items,version=h.version+1
 FROM (
   SELECT h0.version,jsonb_agg(CASE WHEN dest.search_user_id IS NULL THEN r.item
     ELSE jsonb_set(r.item,'{ref,connection_generation}',to_jsonb(confirmed_generation)) END ORDER BY r.ord) AS items
   FROM platform_agent_human_recipients h0
   CROSS JOIN LATERAL jsonb_array_elements(h0.recipients) WITH ORDINALITY r(item,ord)
   LEFT JOIN platform_wecom_identity_mappings src ON src.binding_id=b.id AND src.identity_epoch=b.identity_epoch
     AND src.callback_user_id=r.item->'ref'->>'external_id'
     AND src.connection_generation::text=r.item->'ref'->>'connection_generation' AND src.connection_generation<confirmed_generation
     AND r.item->'ref' @> jsonb_build_object('provider','wecom','kind','user','identity_namespace','user_id',
       'binding_id',b.id,'identity_epoch',b.identity_epoch,'tenant_id',b.app_id,'workspace_id',b.workspace_id,'agent_id',b.agent_id)
   LEFT JOIN platform_wecom_identity_mappings dest ON dest.binding_id=src.binding_id AND dest.identity_epoch=src.identity_epoch
     AND dest.connection_generation=confirmed_generation AND dest.callback_user_id=src.callback_user_id AND dest.search_user_id=src.search_user_id
   WHERE h0.agent_id=b.agent_id GROUP BY h0.version HAVING count(dest.search_user_id)>0
 ) renewed WHERE h.agent_id=b.agent_id AND h.version=renewed.version;
END;
$$;


--
-- Name: platform_wecom_on_identity_confirmed(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_wecom_on_identity_confirmed() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 PERFORM platform_wecom_carry_contacts(NEW,OLD.identity_verified_generation,NEW.connection_generation);
 RETURN NEW;
END;
$$;


