--
-- Name: manager_inputs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.manager_inputs (
    id uuid NOT NULL,
    workspace_id uuid NOT NULL,
    session_id uuid NOT NULL,
    submitted_by uuid,
    admission_epoch bigint NOT NULL,
    seq bigint NOT NULL,
    text text NOT NULL,
    status text DEFAULT 'queued'::text NOT NULL,
    turn_id uuid,
    cancel_reason text,
    rejection_reason text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    started_at timestamp with time zone,
    finished_at timestamp with time zone,
    channel_principal_id uuid,
    channel_generation bigint,
    context_state text,
    context_committed_at timestamp with time zone,
    channel_history_count integer DEFAULT 0 NOT NULL,
    delivery_mode text DEFAULT 'steer'::text NOT NULL,
    source_kind text DEFAULT 'user'::text NOT NULL,
    report_id uuid,
    report_enabled boolean DEFAULT true NOT NULL,
    trigger_agent_loop boolean DEFAULT true NOT NULL,
    batch_input_id uuid,
    web_group_member_epoch bigint,
    web_group_reply_done boolean DEFAULT false NOT NULL,
    trigger_event_id uuid,
    notification_id uuid,
    confirmation_request_id uuid,
    confirmed boolean,
    human_request_id uuid,
    work_assignment_id uuid,
    work_submission_id uuid,
    attachments jsonb DEFAULT '[]'::jsonb NOT NULL,
    CONSTRAINT manager_human_resume_input CHECK (((human_request_id IS NULL) OR ((source_kind = 'human_confirmation'::text) AND trigger_agent_loop AND (delivery_mode = 'queue'::text) AND (confirmation_request_id IS NULL)))),
    CONSTRAINT manager_input_actor CHECK (((((((((submitted_by IS NOT NULL))::integer + ((channel_principal_id IS NOT NULL))::integer) + ((trigger_event_id IS NOT NULL))::integer) + ((notification_id IS NOT NULL))::integer) + ((work_assignment_id IS NOT NULL))::integer) = 1) AND ((channel_principal_id IS NULL) = (channel_generation IS NULL)))),
    CONSTRAINT manager_inputs_attachments_check CHECK ((jsonb_typeof(attachments) = 'array'::text)),
    CONSTRAINT manager_inputs_channel_history_count_check CHECK (((channel_history_count >= 0) AND (channel_history_count <= 100))),
    CONSTRAINT manager_inputs_check CHECK (((confirmation_request_id IS NULL) = (confirmed IS NULL))),
    CONSTRAINT manager_inputs_check1 CHECK (((confirmation_request_id IS NULL) OR ((source_kind = 'user'::text) AND trigger_agent_loop))),
    CONSTRAINT manager_inputs_context_state_check CHECK ((context_state = ANY (ARRAY['pending'::text, 'committed'::text, 'absent'::text, 'unknown'::text]))),
    CONSTRAINT manager_inputs_delivery_mode_check CHECK ((delivery_mode = ANY (ARRAY['steer'::text, 'queue'::text]))),
    CONSTRAINT manager_inputs_seq_check CHECK ((seq > 0)),
    CONSTRAINT manager_inputs_source_kind_check CHECK ((source_kind = ANY (ARRAY['user'::text, 'task_report'::text, 'task_result'::text, 'system'::text, 'human_confirmation'::text, 'work_item_assignment'::text, 'work_item_result'::text, 'work_item_amendment'::text]))),
    CONSTRAINT manager_inputs_status_check CHECK ((status = ANY (ARRAY['queued'::text, 'started'::text, 'processed'::text, 'canceled'::text, 'rejected'::text]))),
    CONSTRAINT manager_inputs_text_check CHECK (((length(text) <= 65536) AND ((length(text) >= 1) OR (jsonb_array_length(attachments) > 0)))),
    CONSTRAINT manager_notification_context_only CHECK (((notification_id IS NULL) OR ((NOT trigger_agent_loop) AND (report_id IS NULL) AND (delivery_mode = 'queue'::text)))),
    CONSTRAINT manager_report_source CHECK (((source_kind = 'task_report'::text) = (report_id IS NOT NULL))),
    CONSTRAINT manager_task_result_server_source CHECK (((source_kind <> 'task_result'::text) OR ((notification_id IS NOT NULL) AND (NOT trigger_agent_loop)))),
    CONSTRAINT manager_work_input_kind CHECK ((((work_assignment_id IS NULL) OR (source_kind = ANY (ARRAY['work_item_assignment'::text, 'work_item_amendment'::text, 'human_confirmation'::text]))) AND ((source_kind <> ALL (ARRAY['work_item_assignment'::text, 'work_item_amendment'::text])) OR (work_assignment_id IS NOT NULL)) AND ((work_submission_id IS NOT NULL) = (source_kind = 'work_item_result'::text)) AND ((source_kind <> ALL (ARRAY['work_item_assignment'::text, 'work_item_amendment'::text, 'work_item_result'::text])) OR (trigger_agent_loop AND (delivery_mode = 'queue'::text)))))
);


