    id uuid NOT NULL,
    workspace_id uuid,
    skill_id uuid NOT NULL,
    sequence bigint NOT NULL,
    version_label text DEFAULT ''::text NOT NULL,
    technical_name text NOT NULL,
    description text NOT NULL,
    manifest jsonb NOT NULL,
    source jsonb NOT NULL,
    storage_identity text NOT NULL,
    key_prefix text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT platform_skill_versions_sequence_check CHECK ((sequence > 0)),
    CONSTRAINT platform_skill_versions_version_label_check CHECK ((length(version_label) <= 100))
);


--
-- Name: platform_skills; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.platform_skills (
    id uuid NOT NULL,
    workspace_id uuid,
    name text NOT NULL,
    description text NOT NULL,
    enabled boolean DEFAULT true NOT NULL,
    version bigint NOT NULL,
    current_version_id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    listed boolean DEFAULT true NOT NULL,
    archived_at timestamp with time zone,
    builtin_key text,
    CONSTRAINT platform_skills_check CHECK (((builtin_key IS NULL) OR (workspace_id IS NULL))),
    CONSTRAINT platform_skills_name_check CHECK (((length(name) >= 1) AND (length(name) <= 100))),
    CONSTRAINT platform_skills_version_check CHECK ((version > 0))
);


--
-- Name: platform_task_link_settings; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.platform_task_link_settings (
    singleton boolean NOT NULL,
    version bigint NOT NULL,
    origin text DEFAULT ''::text NOT NULL,
    enabled boolean DEFAULT true NOT NULL,
    updated_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT platform_task_link_settings_origin_check CHECK ((length(origin) <= 270)),
    CONSTRAINT platform_task_link_settings_singleton_check CHECK (singleton),
    CONSTRAINT platform_task_link_settings_version_check CHECK ((version > 0))
);


--
-- Name: platform_template_catalog_state; Type: TABLE; Schema: public; Owner: -
