--

CREATE INDEX manager_channel_delivery_queries ON public.manager_channel_deliveries USING btree (next_query_at, id) WHERE ((status = ANY (ARRAY['accepted'::text, 'unknown'::text])) AND (provider_request_id IS NOT NULL));


--
-- Name: manager_channel_groups_pending; Type: INDEX; Schema: public; Owner: -
--

