CREATE TRIGGER immutable_owner BEFORE UPDATE OF workspace_id ON public.platform_plugins FOR EACH ROW EXECUTE FUNCTION public.platform_resource_owner_immutable();


--
-- Name: platform_skills immutable_owner; Type: TRIGGER; Schema: public; Owner: -
--

CREATE TRIGGER immutable_owner BEFORE UPDATE OF workspace_id ON public.platform_skills FOR EACH ROW EXECUTE FUNCTION public.platform_resource_owner_immutable();


--
-- Name: manager_inputs manager_planned_task_input_guard; Type: TRIGGER; Schema: public; Owner: -
--

CREATE TRIGGER manager_planned_task_input_guard BEFORE INSERT ON public.manager_inputs FOR EACH ROW EXECUTE FUNCTION public.manager_planned_task_input_guard();


--
-- Name: manager_tasks manager_task_agent_owner; Type: TRIGGER; Schema: public; Owner: -
--

CREATE TRIGGER manager_task_agent_owner BEFORE INSERT OR UPDATE ON public.manager_tasks FOR EACH ROW EXECUTE FUNCTION public.manager_resolve_task_agent();


--
-- Name: manager_conversation_sandboxes manager_task_sandbox_owner; Type: TRIGGER; Schema: public; Owner: -
--

CREATE TRIGGER manager_task_sandbox_owner BEFORE INSERT OR UPDATE ON public.manager_conversation_sandboxes FOR EACH ROW EXECUTE FUNCTION public.manager_check_task_sandbox();


--
-- Name: manager_work_items manager_work_cancel_event; Type: TRIGGER; Schema: public; Owner: -
--

CREATE TRIGGER manager_work_cancel_event AFTER UPDATE OF status ON public.manager_work_items FOR EACH ROW WHEN (((old.status <> new.status) AND (new.status = 'cancelled'::text))) EXECUTE FUNCTION public.manager_work_cancel_event();


--
-- Name: manager_turns manager_work_started; Type: TRIGGER; Schema: public; Owner: -
--

CREATE TRIGGER manager_work_started AFTER INSERT ON public.manager_turns FOR EACH ROW EXECUTE FUNCTION public.manager_work_started();


--
-- Name: platform_channel_bindings platform_wecom_confirmed_contacts; Type: TRIGGER; Schema: public; Owner: -
--

CREATE TRIGGER platform_wecom_confirmed_contacts AFTER UPDATE OF identity_verified_generation ON public.platform_channel_bindings FOR EACH ROW WHEN (((new.provider = 'wecom'::text) AND new.enabled AND (new.app_id = new.external_tenant_id) AND (new.app_id = new.bot_open_id) AND (new.identity_verified_generation = new.connection_generation) AND (old.identity_verified_generation <> new.identity_verified_generation))) EXECUTE FUNCTION public.platform_wecom_on_identity_confirmed();


